#!/usr/bin/env python3
"""Renderiza uma apresentação local, com dados embutidos e sem dependências de rede."""
import base64,html,json,re,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def generate(rows,data,stats):
    def slide(k,title,body,note,cls=''):
        return f'<section class="slide {cls}" aria-labelledby="s{k}" data-title="{html.escape(title)}"><div class="eyebrow">DCC136 · {k:02d} / 12</div><h2 id="s{k}">{title}</h2>{body}<aside class="notes"><strong>Roteiro · </strong>{note}</aside></section>'
    k1,k2=stats[1],stats[2]
    indexed={(r['instance'],r['K'],r['method']):r for r in rows}
    w=stats['worst'];bud=stats['budget']
    display=lambda x:f'{x:,.0f}'.replace(',', '.')
    slides=[]
    slides.append(slide(1,'Locais de prova.<br><em>Decisões que aproximam.</em>', '''<p class="lede">Construção gulosa randomizada, VND e Busca Tabu<br>para alocar candidatos com capacidade e compatibilidade.</p><div class="coverline"><span>Bruno Keil · UFJF<br>Inteligência Computacional · 2026.3</span><span>28 instâncias<br>3.360 execuções · K = 1 e 2</span></div>''','0:00–0:35 · Apresentar o objetivo e os dois níveis de decisão: tipos nas escolas e destinos dos candidatos. K é informado na execução; o algoritmo escolhe os tipos de cada escola.','cover'))
    slides.append(slide(2,'Até K tipos por escola.<br>Menos deslocamento.', '''<div class="split"><div><p class="lede">Planejar exames de ingresso com menor deslocamento dos candidatos e respeito às vagas.</p><div class="formula">D = Σ d(i, aᵢ)</div><p>Cada candidato tem um único destino compatível. A escola é utilizada quando recebe candidatos.</p></div><div class="rules"><div><b>01</b><span>Até K tipos por escola<br><small>K = 1 ou 2 na execução</small></span></div><div><b>02</b><span>Capacidade compartilhada<br><small>Soma das vagas das salas</small></span></div><div><b>03</b><span>Matriz de distâncias<br><small>Sem custo de abertura</small></span></div></div></div>''','0:35–1:15 · Motivar o problema de planejamento de exames. Os locais não têm tipo previamente fixado: nossa solução escolhe esse tipo. K=1 e K=2 são casos exigidos; a capacidade é compartilhada pelos tipos habilitados.'))
    slides.append(slide(3,'Uma solução em dois vetores.', '''<div class="split"><div><div class="caption">ESCOLA → TIPOS · EXEMPLO K=1</div><div class="vector"><span>E1<br><b>M2</b></span><span>E2<br><b>M1</b></span><span>E3<br><b>—</b></span></div><div class="caption">CANDIDATO → ESCOLA</div><div class="code">a = [E2, E2, E2, E2,<br>　　 E1, E1, E1, E1]</div></div><div><p class="lede">Cargas e distância são atualizadas a cada movimento.</p><p>Máscaras Sⱼ guardam até K tipos: |Sⱼ| ≤ K. Em K=2, uma escola pode habilitar M1 e M2. Guardamos cargas por tipo e não alocados (<code>−1</code>).</p><p class="callout">Distâncias em inteiros de milionésimos de km: comparação exata até seis casas decimais.</p></div></div>''','1:15–1:50 · Explicar índices na ordem do arquivo, IDs preservados e capacidade agregada. O vetor K=1 será usado no exemplo didático; K=2 usa a mesma representação.'))
    slides.append(slide(4,'Antes de otimizar,<br>verificar se é possível.', '''<div class="split"><div><p class="lede">Um modelo inteiro pequeno certifica o atendimento máximo C*.</p><p>Maximiza contagens por escola e tipo, com limite de vagas, demanda e Σₜ zⱼₜ ≤ K.</p><div class="formula">1º atendimento · 2º distância</div></div><div class="callout"><div class="big">6 ≠ 5</div><h3>Seis tipos. Cinco escolas.</h3><p>I2 G2: 109 candidatos e 121 vagas. K=1 atende no máximo 96; K=2 atende todos os 109.</p><p>Seis tipos excedem cinco escolas em K=1. Em K=2, o limite é dez tipos; a capacidade ainda precisa ser verificada.</p></div></div><p class="footnote">SciPy/HiGHS certifica atendimento; não otimiza distâncias. Timeout é inconclusivo.</p>''','1:50–2:35 · I2 G2 é inviável em K=1 e viável em K=2; a classificação depende do parâmetro. Não atribuir a falha à heurística. Uma solução parcial de menor distância não deve ser comparada a uma solução completa.'))
    slides.append(slide(5,'Construir sem fechar<br>as próximas escolhas.', f'''<div class="steps"><div><b>01 / Habilitar tipos</b><p>Combinar ganho de atendimento por fluxo, uso da capacidade e proximidade.</p><code>score = g/bₜ + g/Qⱼ − proximidade</code></div><div><b>02 / Alocar por regret</b><p>Priorizar quem perde mais ao abrir mão da melhor escola. Uma única opção vem primeiro.</p><code>regret = d₂ − d₁</code></div><div><b>03 / Reparar impasses</b><p>Caminhos aumentantes deslocam candidatos até alcançar uma vaga compatível.</p><code>candidato → escola → … → vaga</code></div></div><p class="callout">RCL com α = 0,3 preserva preferência gulosa e varia as escolhas. Fallback: {k1["fallback"]} de 1.680 construções em K=1; {k2["fallback"]} de 1.680 em K=2.</p>''','2:35–3:30 · Justificar a prioridade a candidatos com poucas alternativas. Escolhas de tipos podem bloquear cobertura; explicitar que o certificado também pode fornecer os tipos no fallback.'))
    slides.append(slide(6,'Três formas de mudar<br>a mesma solução.', '''<div class="steps neighborhoods"><div><span class="nmark">N1</span><h3>Realocar</h3><p>Um candidato muda de escola compatível.</p><code>Δ = dᵢᵦ − dᵢₐ</code><p class="muted">Até cinco destinos próximos.</p></div><div><span class="nmark">N2</span><h3>Trocar</h3><p>Dois candidatos do mesmo tipo permutam destinos.</p><code>Δ = dᵢᵦ + dₕₐ − dᵢₐ − dₕᵦ</code><p class="muted">Preserva cargas das escolas.</p></div><div><span class="nmark">N3</span><h3>Mudar tipos</h3><p>Adicionar, substituir ou permutar tipos; reconstruir alocações afetadas.</p><p class="muted">Fluxo filtra perda de atendimento. Seis reconstruções por chamada.</p></div></div>''','3:30–4:20 · N1/N2 atuam nos destinos. N3 muda a estrutura. A correção reconsidera candidatos dos tipos recém-habilitados para poder ocupar uma escola antes vazia.'))
    slides.append(slide(7,'Descer ou atravessar<br>um vale de piora.', '''<div class="split method"><div><span class="tag green">VND</span><h3>Aceitar melhora estrita.</h3><p>N1 → N2 → N3.<br>Após melhora, voltar à N1.</p><p>Melhor melhoria entre os movimentos examinados.</p></div><div><span class="tag red">BUSCA TABU</span><h3>Explorar além da descida.</h3><p>Escolher o melhor movimento admissível, mesmo com piora temporária.</p><p>Memória tabu [5,12], aspiração e arquivo da melhor solução.</p></div></div><div class="formula smallformula">f(s) = D(s) + λ · excesso + μ · (não alocados + incompatíveis)</div><p class="footnote">Penalidades iniciais dominam a distância; λ adapta na tabu. A solução devolvida preserva capacidade e atendimento certificado.</p>''','4:20–5:10 · Explicar tabu como prevenção de retorno imediato, aspiração pela melhor completa viável e adaptação de λ a cada cinco estados. Na campanha: VND até o ótimo local (uma iteração = uma exploração de Nk); tabu com '+str(bud['tabu_max_iter'])+' iterações ou '+str(bud['tabu_stagnation'])+' sem melhora, tempo desativado.'))
    slides.append(slide(8,'Um local vazio pode<br>guardar uma melhoria.', '''<div class="example-toolbar"><span class="tag green">EXEMPLO · 8 CANDIDATOS · K=1</span><button id="example-toggle" type="button">Aplicar N3 →</button></div><div class="split example"><div><div class="caption" id="example-caption">CONSTRUÇÃO · E1/M2 E E2/M1</div><div id="school-demo"></div></div><div><div class="big" id="example-cost">56 <small>km</small></div><p class="lede" id="example-description">O construtivo atende todos com E1 e E2. E3 permanece vazia.</p><p>N1 e N2 não melhoram esses tipos fixos. N3 habilita M1 em E3: 56 → 42 km (−25%).</p><p class="footnote">Demonstração com α=0 e até 1000 reconstruções, para examinar todas as propostas do exemplo.</p></div></div>''','5:10–6:25 · Clique em Aplicar N3. Inicial: M1 em E2 custa 33; M2 em E1 custa 23. Habilitar M1 em E3 libera candidatos M1. C3 tem regret 10 e C1 regret 4: ocupam E3. M1 passa a custar 19, total 42; melhora 25%. Capacidades 4,4,2. Este exemplo didático usa K=1; o experimento compara ambos os valores de K.'))
    slides.append(slide(9,'O que limita a qualidade.', f'''<div class="split"><div><span class="tag red">CASO REAL · {w['label']} · K={w['K']}</span><h3>Ótimo local ainda pode ser ruim.</h3><p>Em 30 sementes, o VND termina entre <strong>{display(w['min'])} e {display(w['max'])} km</strong>; média {w['gap']:.1f}% acima da melhor solução conhecida ({display(w['ref'])} km).</p><p>Ótimos locais de N1/N2 com tipos ruins; N3 amostrada (seis reconstruções) raramente escapa sem aceitar piora.</p></div><div><span class="tag green">LIÇÃO DE PROJETO</span><h3>Habilitar precisa realocar.</h3><p>Preservar candidatos de todas as escolas inalteradas impedia ocupar uma escola recém-habilitada.</p><p>N3 agora reconsidera os candidatos dos tipos novos, tanto em K=1 quanto em K=2.</p></div></div><p class="callout">A variação observada não isola uma causa. Encerrar a busca não prova ótimo local completo ou global.</p>''','6:25–7:10 · Usar o pior caso do VND como exemplo real: todas as soluções são completas e comparáveis no mesmo K. Atribuir causas à exploração é uma hipótese; não houve ablação para isolá-las. A regressão de N3 testa um problema já corrigido.'))
    slides.append(slide(10,'K muda a viabilidade.<br>A busca muda a distância.', f'''<div class="metricline"><div><b>28</b><span>instâncias distintas</span></div><div><b>30</b><span>sementes por método e K</span></div><div><b>6.720</b><span>soluções validadas</span></div><div><b>{k1['feasible']} → {k2['feasible']}</b><span>viáveis: K=1 → K=2</span></div></div><div class="result-toolbar"><label for="instance-select">Explorar instância</label><select id="instance-select"></select><span id="result-status" class="tag"></span></div><div id="results-table" class="tablewrap"></div><p class="footnote">Km; média ± desvio padrão amostral para construção e busca. Total = C + BL + (leitura + pré-checagem)/30, em segundos. Distâncias parciais e completas não são comparáveis.</p><p id="precheck-detail" class="footnote"></p>''','7:10–8:20 · O seletor inicia em I2 G2 e exibe K=1 e K=2 lado a lado: 96 versus 109 atendidos. Mostrar também I1 G1 ou I2 G9. Explicar dispersão inicial/final e custo do solver compartilhado por 30 sementes. Tempos são de máquina compartilhada.','results'))
    comparisons=''.join(f"<p>K={K}: tabu {stats[K]['wins']} · VND {stats[K]['vnd_wins']} · {stats[K]['ties']} " + ('empate' if stats[K]['ties']==1 else 'empates') + '.</p>' for K in (1,2))
    slides.append(slide(11,'A trajetória também<br>explica o resultado.', f'''<div class="split"><div><div class="result-toolbar"><label for="curve-k-select">Convergência em I1 G1</label><select id="curve-k-select"><option value="1">K=1</option><option value="2">K=2</option></select><span id="curve-k-label">K=1</span></div><div id="convergence-chart"></div></div><div><p class="lede">Vitórias por menor distância média, em 28 instâncias por K.</p>{comparisons}<p>VND para no ótimo local; a tabu continua após ele, com custo de tempo maior.</p><p class="callout">Comparação descritiva, sem teste de significância ou alegação de superioridade universal.</p></div></div><p class="footnote">Melhor distância média arquivada por iteração. Curvas encerradas mantêm o último valor.</p>''','8:20–9:10 · Ler a curva como melhor solução arquivada, não custo do estado corrente. A comparação de métodos ocorre dentro de cada K. Mostrar o seletor de K se houver tempo. Processos paralelos tornam os tempos indicativos.'))
    slides.append(slide(12,'Construir. Reparar.<br><em>Reconsiderar os tipos.</em>', '''<div class="split"><div><p class="lede">Escolher tipos e destinos em conjunto reduz bloqueios de alocação.</p><p><strong>Principais dificuldades:</strong> preservar atendimento ao mudar tipos, reconstruir N3 e limitar o custo de exploração.</p><p>Melhorias: amostragem adaptativa em N3 e comparação por tempo e avaliações.</p></div><div class="closing"><div class="caption">ENTREGA · 26/10/2026 ÀS 10H</div><p>C++17 · K=1 ou K=2 na execução<br>Relatório SBC · slides HTML e PDF<br>Instâncias e resultados completos</p><a href="https://github.com/brunokeil/Trabalho_Inteligencia_Computacional">github.com/brunokeil/Trabalho_Inteligencia_Computacional ↗</a><br><a id="report-download" class="offline-download" href="data:application/pdf;base64,/* REPORT_PDF */" download="relatorio.pdf">Baixar relatório PDF</a><br><a class="offline-download" href="data:text/csv;base64,/* SUMMARY_CSV */" download="final_resumo.csv">Baixar resultados CSV</a></div></div><p class="footnote">SciPy/HiGHS certifica atendimento em ambos os valores de K. O fallback não foi necessário nas 3.360 construções; a dependência do solver permanece.</p>''','9:10–10:00 · Concluir com o papel de cada componente. Destacar dificuldades de reconstrução e orçamento, a avaliação de K=1 e K=2 e a dependência do solver. Código e resultados estão no GitHub indicado; os arquivos incorporados podem ser baixados offline.'))
    compact={}
    for r in rows:compact.setdefault(r['instance'],{}).setdefault(r['K'],{})[r['method']]=r
    curves={}
    for K in (1,2):
        curves[K]={}
        for method in ('vnd','tabu'):
            from gerar_entrega import mean_curve
            curves[K][method]=mean_curve(data['Instancia1_G1.txt',K,method]['runs'])
        n=max(len(c) for c in curves[K].values())
        for method in ('vnd','tabu'):
            c=curves[K][method];curves[K][method]=c+[c[-1]]*(n-len(c))
    template=(ROOT/'docs/apresentacao_template.html').read_text()
    output=template.replace('<!-- SLIDES -->','\n'.join(slides)).replace('/* RESULTS */',json.dumps(compact,ensure_ascii=False).replace('</','<\\/')).replace('/* CURVES */',json.dumps(curves))
    output=output.replace('/* SUMMARY_CSV */',base64.b64encode((ROOT/'resultados/final_resumo.csv').read_bytes()).decode())
    (ROOT/'docs/apresentacao.html').write_text(output)
    incorporar_relatorio()


def incorporar_relatorio():
    """Atualiza somente o PDF incorporado depois de recompilar o relatório."""
    path=ROOT/'docs/apresentacao.html'
    pdf=(ROOT/'docs/relatorio.pdf').read_bytes()
    s=path.read_text()
    s,count=re.subn(r'(id="report-download"[^>]*href=")data:application/pdf;base64,[^"]*',
                    lambda m:m[1]+'data:application/pdf;base64,'+base64.b64encode(pdf).decode(),s)
    assert count==1, 'Link de download do relatório ausente'
    path.write_text(s)

if __name__=='__main__':
    incorporar_relatorio()
